// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(113000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await page.goto(`${baseUrl}/product/OLJCESPC7Z`);
    await page.locator("#quantity").selectOption("2");
    await page.getByRole("button", { name: "Add To Cart" }).click();
    await expect(page.getByRole("link", { name: "Cart icon" })).toContainText("2");
    await page.goto(`${baseUrl}/assistant`);
    // EXPECTED FAILURE - documents a real gap. The PR adds a cart badge to the SITE HEADER, and
    // /assistant renders that same header, but assistantHandler never puts "cart_size" into the
    // template data - so the badge is force-hidden here even though the cart holds 2 items.
    // The two assertions below encode the CORRECT behaviour and fail until the handler is fixed.
    await expect(page.locator('#cart-count-badge')).toBeVisible();
    await expect(page.locator('#cart-count-badge')).toHaveText('2');
    await page.goto(`${baseUrl}/cart`);
    await expect(page.getByTestId("cart-heading")).toContainText("Cart (2)");
    // Control: the cart genuinely still holds 2 items, so the hidden badge above is not an empty cart.
    await expect(page.locator('#cart-count-badge')).toHaveText('2');
});
